pragma solidity 0.8.7;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

contract AmiraDiTransilvania is ERC721, Ownable {
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIds;
    address amiraAddress;
    uint256 public pricePerArt = 300000000000000000000; // 300 MATIC base price 300000000000000000000

    constructor() ERC721("AmiraDiTransilvania", "AMR") {
     amiraAddress = msg.sender;
     for(uint x = 0; x < 15; x++) {
      _tokenIds.increment();
      uint256 id = _tokenIds.current();
      super._mint(msg.sender, id);
    }
  }

    function _baseURI() internal pure override returns (string memory) {
        return "ipfs://Qmb1Db4cB7w5y1rgHrCD581XCMTtwATQq33LFwQCisk9Zm/";
    }

    function withdraw() external onlyOwner {
        address payable _owner = payable(owner());
        _owner.transfer(address(this).balance);
     }

     function buyArt(uint256 id) public payable returns(uint256) {
       require(msg.value >= pricePerArt, "Ether value sent does not satisify");
       require(amiraAddress == ownerOf(id), "Already sold");
       _safeTransfer(amiraAddress, msg.sender, id, "");
       pricePerArt = pricePerArt + 100000000000000000000; // 50000000000000000000
       return id;
     }

    function setPrice(uint256 _newPrice) public onlyOwner() {
        pricePerArt = _newPrice;
    }

    function getPrice() public view returns(uint256) {
      return pricePerArt;
    }
}

