        bytes memory data
    ) public virtual  {

    }

      function safeTransferFrom(
        address from,
        address to,
        uint256 id
    ) public virtual  {

    }

        function safeMint(address to, string memory uri) public returns (uint256) {
      uint256 id = 0;
        return id;
    }


