contract EgyLove is ERC1155, Ownable, Pausable   {
    constructor() ERC1155("ipfs://QmVHgdZALmpEeuPDMLX1qRLrkrcTj3o9nBKx7grMjmF7qQ/{id}.json") {
        _mint(msg.sender, 0, 20000000 * 10 ** 18, "EGY Flare");
        _mint(msg.sender, 1, 10000000 * 10 ** 18, "Black Hole");
    }

  address energyExchanger;

   function setEnergyExchanger(address _energyExchanger) public onlyOwner() { 
